style.css:
/* Altera a cor da borda da barra de pesquisa ao clicar */
input[type="text"]:focus {
  border-color: #DE3163; /* Cor da borda ao clicar */
}

/* Altera o background das opções de pesquisa ao passar o mouse */
ul[role="listbox"] li:hover {
  background-color: #DE3163; /* Cor do background ao passar o mouse */
}
